mapper.select:
SELECT id, CAST(raw_payload AS CHAR) AS raw_payload, process_status
FROM tracking_event
WHERE provider_id = #{providerId} AND tracking_no = #{trackingNo} AND event_id = #{eventId}

mapper.update:
UPDATE shipment_order
SET current_status = #{toStatus}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{orderId} AND current_status = #{fromStatus}
